    private static byte[] hex(String value) {
        byte[] bytes = new byte[value.length() / 2];
        for (int i = 0; i < bytes.length; i++) {
            bytes[i] = (byte) Integer.parseInt(value.substring(i * 2, i * 2 + 2), 16);
        }
        return bytes;
    }

    private static Stream input(byte[] plaintext, int capacity) {
        byte[] bytes = new byte[capacity];
        Arrays.fill(bytes, (byte) 0x5a);
        System.arraycopy(plaintext, 0, bytes, 0, plaintext.length);
        Stream stream = new Stream(bytes);
        stream.currentOffset = plaintext.length;
        stream.bitOffset = 37;
        return stream;
    }

    @Test public void independentVectorsProveSignedBigEndianModularExponentiationAndOutput() {
        for (String vector : VECTORS) {
            String[] pair = vector.split(":");
            byte[] plaintext = hex(pair[0]);
            byte[] ciphertext = hex(pair[1]);
            Stream stream = input(plaintext, 260);
            byte[] original = stream.buffer.clone();
            byte[] identity = stream.buffer;
            stream.encryptRsaBlock();
            assertSame(identity, stream.buffer);
            assertEquals(pair[0], ciphertext.length, stream.buffer[0] & 255);
            assertArrayEquals(pair[0], ciphertext, Arrays.copyOfRange(stream.buffer, 1, ciphertext.length + 1));
            assertEquals(ciphertext.length + 1, stream.currentOffset);
            assertEquals(37, stream.bitOffset);
            assertArrayEquals(Arrays.copyOfRange(original, stream.currentOffset, original.length),
                    Arrays.copyOfRange(stream.buffer, stream.currentOffset, stream.buffer.length));
        }
    }

    @Test public void prefixLengthExcludesTailAndLeadingZerosDoNotChangeInteger() {
        Stream one = input(hex("0080"), 260);
        Stream other = input(hex("0080"), 260);
        Arrays.fill(other.buffer, 2, other.buffer.length, (byte) 0xa7);
        one.encryptRsaBlock(); other.encryptRsaBlock();
        assertEquals(one.currentOffset, other.currentOffset);
        assertArrayEquals(Arrays.copyOf(one.buffer, one.currentOffset), Arrays.copyOf(other.buffer, other.currentOffset));
        Stream padded = input(new byte[140], 260);
        padded.buffer[139] = 1;
        byte[] original = padded.buffer.clone();
        padded.encryptRsaBlock();
        assertEquals(2, padded.currentOffset);
        assertEquals(1, padded.buffer[0]); assertEquals(1, padded.buffer[1]);
        assertArrayEquals(Arrays.copyOfRange(original, 2, original.length), Arrays.copyOfRange(padded.buffer, 2, padded.buffer.length));
        Stream negative = input(hex("80"), 260);
        negative.encryptRsaBlock();
        assertFalse(Arrays.equals(Arrays.copyOf(one.buffer, one.currentOffset), Arrays.copyOf(negative.buffer, negative.currentOffset)));
    }

    @Test public void lengthCountsMinimalSignedCiphertextIncludingSignPadding() {
        boolean saw128 = false, saw129 = false;
        for (String vector : VECTORS) {
            String[] pair = vector.split(":");
            byte[] expected = hex(pair[1]);
            Stream stream = input(hex(pair[0]), 260);
            stream.encryptRsaBlock();
            if (expected.length == 129) {
                saw129 = true;
                assertEquals(0, stream.buffer[1]);
                assertTrue((stream.buffer[2] & 128) != 0);
                assertEquals(129, stream.buffer[0] & 255);
            }
            if (expected.length == 128) saw128 = true;
        }
        assertTrue(saw128); assertTrue(saw129);
        for (int value = 0; value <= 1; value++) {
            Stream stream = input(new byte[] {(byte) value}, 2);
            stream.encryptRsaBlock();
            assertArrayEquals(new byte[] {1, (byte) value}, stream.buffer);
            assertEquals(2, stream.currentOffset);
        }
    }

    @Test public void emptyAndNegativeLengthsFailAfterResetWithoutChangingBufferOrBitOffset() {
        Stream stream = input(new byte[0], 8);
        byte[] original = stream.buffer.clone();
        try { stream.encryptRsaBlock(); fail("empty integer"); } catch (NumberFormatException expected) { }
        assertEquals(0, stream.currentOffset); assertEquals(37, stream.bitOffset);
        assertArrayEquals(original, stream.buffer);
        stream.currentOffset = -1;
        try { stream.encryptRsaBlock(); fail("negative length"); } catch (NegativeArraySizeException expected) { }
        assertEquals(0, stream.currentOffset); assertEquals(37, stream.bitOffset);
        assertArrayEquals(original, stream.buffer);
    }

    @Test public void truncatedInputFailsWhileReadingAndShortOutputRetainsPartialMutation() {
        Stream truncated = new Stream(new byte[] {1, 2, 3});
        truncated.currentOffset = 4;
        truncated.bitOffset = 37;
        try { truncated.encryptRsaBlock(); fail("truncated prefix"); } catch (ArrayIndexOutOfBoundsException expected) { }
        assertEquals(4, truncated.currentOffset); assertEquals(37, truncated.bitOffset);
        assertArrayEquals(new byte[] {1, 2, 3}, truncated.buffer);
        Stream shortOutput = input(new byte[] {0}, 1);
        try { shortOutput.encryptRsaBlock(); fail("short output"); } catch (ArrayIndexOutOfBoundsException expected) { }
        assertEquals(2, shortOutput.currentOffset); assertEquals(37, shortOutput.bitOffset);
        assertArrayEquals(new byte[] {1}, shortOutput.buffer);
    }
